61: 
62: 		if strings.HasPrefix(trimLine, "```") {
63: 			inCodeFence = !inCodeFence
64: 			continue
65: 		}
66: 
67: 		if inCodeFence {
68: 			continue
69: 		}
70: 		
71: 		if strings.HasPrefix(trimLine, "## ") && currentSection != "" && !strings.HasPrefix(trimLine, "## Completion Report") {
72: 			break
73: 		}
74: 
75: 		if strings.HasPrefix(trimLine, "### ") {
76: 			currentSection = strings.TrimPrefix(trimLine, "### ")
77: 			continue
78: 		}
79: 
80: 		if trimLine == "" || trimLine == "(none)" {
81: 			continue
