101: 				var pathPart, descPart string
102: 				if idx := strings.Index(item, " — "); idx != -1 {
103: 					pathPart = item[:idx]
104: 					descPart = item[idx+len(" — "):]
105: 				} else if idx := strings.Index(item, " - "); idx != -1 {
106: 					pathPart = item[:idx]
107: 					descPart = item[idx+len(" - "):]
108: 				} else {
109: 					pathPart = item
