113: 				pathPart = strings.Trim(pathPart, "` ")
114: 				descPart = strings.TrimSpace(descPart)
115: 				
116: 				if strings.Contains(pathPart, " ") || (!strings.Contains(pathPart, "/") && !strings.Contains(pathPart, ".")) {
